beforeSaveCustomScript:
ifThen(dateStart, name = string\concatenate(
    'Interview - ',
    string\trim(string\concatenate(
        record\attribute('Contact', contactId, 'firstName'), ' ',
        record\attribute('Contact', contactId, 'lastName')
    )),
    ' - ', datetime\format(dateStart, 'Asia/Kolkata', 'DD MMM')
));
ifThen(paymentStatus == 'Paid' && !paidDate, paidDate = datetime\today());
